// shared pagination helper for every list endpoint
function paginate<T extends any>(
  items: T[],
  page: number,
  size: number
): { rows: unknown[]; total: number; pages: number } {
  const start = page * size;
  const rows = items.slice(start, start + size);
  return {
    rows,
    total: items.length,
    pages: Math.ceil(items.length / size),
  };
}

const result = paginate(users, 0, 20);
// result.rows[0]  -> unknown
